insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_127'
from (values
('127.875.d.1.A',3,'A technician at a golf-course shop notices a recalled throttle part on a customer''s mower and warns him before returning it. She is acting on:','["her ethical and legal responsibilities to the customer and the public", "a shop shortcut", "a way to save time", "an optional courtesy"]'::jsonb,0,'Safety recalls carry legal duties.','original'),
('127.875.d.1.A',4,'A shop copies a competitor''s service manual without permission. This is a problem mainly because it:','["is encouraged by industry", "violates copyright law and professional ethics", "saves the shop money legally", "has no consequences"]'::jsonb,1,'Copying protected manuals is illegal.','original'),
('127.875.d.1.B',3,'During a busy Saturday rush, a technician thanks each waiting customer and keeps his bay orderly. He is showing:','["poor manners", "careless habits", "proper etiquette and professional behavior", "disinterest"]'::jsonb,2,'Courtesy under pressure.','original'),
('127.875.d.1.B',4,'A coworker keeps interrupting while a customer describes a noise. The best professional response is to:','["join the interruption", "raise your voice", "leave the customer", "politely ask him to wait so the customer can finish"]'::jsonb,3,'Respect the speaker.','original'),
('127.875.d.1.C',3,'A technician arrives with clean coveralls, closed-toe boots and tied-back hair. This reflects appropriate:','["personal appearance and hygiene for the workplace", "careless dress", "poor hygiene", "unsafe clothing"]'::jsonb,0,'Neat dress shows professionalism.','original'),
('127.875.d.1.C',4,'Why should a technician wear closed-toe, slip-resistant boots in the engine shop?','["they reduce engine noise", "they protect feet from dropped parts and oily floors", "they are required by customers", "they look fashionable"]'::jsonb,1,'Footwear is PPE.','original'),
('127.875.d.1.D',3,'A technician emails a vendor a clear parts request, then calls a customer to confirm pickup time. She is using:','["avoidance", "only gestures", "written and oral communication skills with employability in mind", "no communication"]'::jsonb,2,'Both channels matter.','original'),
('127.875.d.1.D',4,'Which email to a supplier is most effective?','["one that says ''send stuff''", "one that is all in capital letters", "one with no subject line", "one that lists the part number, quantity and needed date"]'::jsonb,3,'Be specific.','original'),
('127.875.d.1.E',3,'A student drafts a clear procedure for adjusting a carburetor, with torque values, tools and cautions in numbered steps. This is advanced:','["technical writing and preparation", "story writing", "note passing", "poetry"]'::jsonb,0,'Precise instructions.','original'),
('127.875.d.1.E',4,'Compared with casual writing, technical writing for a repair manual should be:','["emotional and long", "exact, concise and organized", "random and unordered", "decorative and vague"]'::jsonb,1,'Manuals need clarity.','original'),
('127.875.d.1.F',3,'A student explains a four-stroke cycle to visiting parents, first with notes and later answering questions on the spot. She is demonstrating:','["mumbling", "reading only", "prepared and extemporaneous speaking skills", "silence"]'::jsonb,2,'Both prepared and impromptu.','original'),
('127.875.d.1.F',4,'Which habit makes a technical presentation more effective?','["speaking too softly", "using only jargon", "reading from the slide", "facing the audience and using plain language"]'::jsonb,3,'Engage the audience.','original'),
('127.875.d.2.A',3,'A student helps organize a fundraiser and a leadership retreat for her student organization. She is participating in:','["planning and developing leadership and skill development activities", "avoiding responsibility", "ignoring teammates", "skipping events"]'::jsonb,0,'Leadership is built by doing.','original'),
('127.875.d.2.A',4,'A student chairing a committee practices leadership best by:','["blaming others", "assigning tasks fairly and following up on results", "doing everything alone", "avoiding decisions"]'::jsonb,1,'Leaders delegate.','original'),
('127.875.d.2.B',3,'A student uses a career and technical student organization''s mentor list, conferences and competitive events to meet employers. She is:','["avoiding contacts", "wasting time", "using organizational resources to grow her career", "hiding her skills"]'::jsonb,2,'Use resources.','original'),
('127.875.d.2.B',4,'A student organization chapter''s competitive events benefit a student mainly by:','["reducing teamwork", "avoiding feedback", "removing practice", "testing technical skills against industry standards"]'::jsonb,3,'Contests set standards.','original'),
('127.875.d.2.C',3,'A student keeps a portfolio of her certificates, competition scores and completed repair projects. She is:','["recording individual progress to document achievements", "avoiding records", "hiding results", "discarding work"]'::jsonb,0,'Portfolios show growth.','original'),
('127.875.d.2.C',4,'A portfolio helps a graduate most when she is:','["skipping the interview", "applying for a job and needs to show proof of her skills", "shopping for tools", "avoiding references"]'::jsonb,1,'Proof of skill.','original'),
('127.875.d.3.A',3,'A shop owner invests in fuel-injected, battery-electric and hybrid outdoor equipment training. This reflects:','["no change in the trade", "a drop in demand", "the impact of emerging technologies on the small engine industry", "a fixed market"]'::jsonb,2,'Tech changes demand.','original'),
('127.875.d.3.A',4,'How might robotic mowers change the work of a small-engine shop?','["only paint work remains", "shops must close", "no repairs will be needed", "technicians may service batteries, sensors and software"]'::jsonb,3,'New skills required.','original'),
('127.875.d.3.B',3,'A group compares the effects of tighter emission rules and a technician shortage on repair shops. They are:','["comparing and contrasting issues affecting the industry", "describing a hobby", "avoiding discussion", "ignoring problems"]'::jsonb,0,'Compare issues.','original'),
('127.875.d.3.B',4,'Which is a contrast between the emissions issue and the technician-shortage issue?','["both are about paint", "emissions affects equipment design; the shortage affects staffing", "neither affects the shop", "both only affect tires"]'::jsonb,1,'Different impacts.','original'),
('127.875.d.3.C',3,'A student researches how fuel prices and overseas parts supply affect repair costs. She is describing:','["personal hobbies", "unrelated topics", "local and global market conditions that impact the industry", "only weather"]'::jsonb,2,'Markets affect cost.','original'),
('127.875.d.3.C',4,'A global supply-chain delay for engine parts is likely to cause:','["faster repairs", "lower prices only", "no effect", "longer repair times and higher parts prices"]'::jsonb,3,'Scarcity raises price.','original'),
('127.875.d.4.A',3,'A shop writes a plan to inspect lifts monthly, calibrate gauges yearly and review results to improve the plan. This involves developing, evaluating and performing:','["preventative maintenance plans and systems", "random chores", "vacation plans", "sales plans"]'::jsonb,0,'Plan, evaluate, perform.','original'),
('127.875.d.4.A',4,'Evaluating a preventative maintenance plan means:','["raising prices", "reviewing records to see whether it prevents breakdowns", "ignoring the data", "skipping inspections"]'::jsonb,1,'Check the plan''s results.','original'),
('127.875.d.4.B',3,'A technician fills in the repair order with the customer''s complaint, the cause found and the correction made. This is:','["losing data", "avoiding forms", "completing repair orders and paperwork for small engine work", "hiding steps"]'::jsonb,2,'The three Cs of a repair order.','original'),
('127.875.d.4.B',4,'The ''cause'' line on a repair order records:','["the date only", "the shop''s address", "the customer''s phone", "what was found to have created the customer''s complaint"]'::jsonb,3,'Cause explains the problem.','original'),
('127.875.d.4.C',3,'A technician combines $38 for parts, $15 in shop supplies and 1.5 hours at $70 an hour for a quote. He is:','["estimating parts and labor costs on a repair order", "skipping the math", "guessing blindly", "hiding fees"]'::jsonb,0,'Parts plus labor plus supplies.','original'),
('127.875.d.4.C',4,'A job needs $52 in parts and 3 hours at $65 per hour. The total estimate is:','["$320", "$247", "$117", "$195"]'::jsonb,1,'52 + 195 = 247.','original'),
('127.875.d.4.D',3,'A shop owner tracks how many billable hours each technician completes compared with hours worked. This describes:','["paint selection", "personal hobbies", "business management principles such as technician productivity", "tire storage"]'::jsonb,2,'Productivity is measured.','original'),
('127.875.d.4.D',4,'If a technician works 40 hours and bills 30 hours, his efficiency is:','["25 percent", "30 percent", "133 percent", "75 percent"]'::jsonb,3,'30 ÷ 40 = 0.75.','original'),
('127.875.d.4.E',3,'A technician locates a carburetor''s float-height specification in the manufacturer''s service manual. She is:','["locating, reading and interpreting service repair information", "ignoring data", "skipping reference", "guessing"]'::jsonb,0,'Look it up.','original'),
('127.875.d.4.E',4,'A technician finding conflicting specifications between a parts catalog and the engine''s service manual should:','["use the catalog only", "use the manufacturer''s service manual for the correct specification", "guess the average", "pick the lower value"]'::jsonb,1,'Service manual governs.','original'),
('127.875.d.5.A',3,'A technician consults a service manual, a manufacturer hotline and an online forum before diagnosing a hard-starting engine. She is:','["relying on guesses", "ignoring references", "using a variety of resources to research, troubleshoot and diagnose problems", "skipping diagnosis"]'::jsonb,2,'Use many resources.','original'),
('127.875.d.5.A',4,'Which resource is the most reliable for a torque specification?','["an anonymous forum post", "a social-media video", "a neighbor''s memory", "the manufacturer''s published service manual"]'::jsonb,3,'Official data first.','original'),
('127.875.d.5.B',3,'A student suspects a dirty jet is causing surging, changes only that one factor and tests the result. She is applying:','["the scientific method to small engine technology", "guessing", "random swapping", "luck"]'::jsonb,0,'Test one variable.','original'),
('127.875.d.5.B',4,'In the scientific method, an engine technician''s hypothesis should be:','["a random guess", "a testable explanation, such as ''a clogged jet causes the lean condition''", "a final conclusion", "an unrelated fact"]'::jsonb,1,'Hypotheses are testable.','original'),
('127.875.d.6.A',3,'A student writes a proposal to restore a vintage tiller for a county fair, listing materials and a budget. She is:','["ignoring costs", "skipping steps", "developing a project proposal", "avoiding planning"]'::jsonb,2,'Proposals set goals.','original'),
('127.875.d.6.A',4,'A project proposal usually includes a:','["playlist", "menu", "dance routine", "timeline, a parts list and an estimated budget"]'::jsonb,3,'Complete plan.','original'),
('127.875.d.6.B',3,'A student logs each compression test, part replaced and date for every engine she repairs. She is:','["developing and maintaining records for small engine work", "avoiding documentation", "losing data", "skipping notes"]'::jsonb,0,'Keep service records.','original'),
('127.875.d.6.B',4,'Maintenance records help a shop when a customer returns with a warranty question because they:','["hide past work", "show what was done and when", "replace the warranty", "slow the process"]'::jsonb,1,'Records support claims.','original'),
('127.875.d.6.C',3,'A class records the compression of ten engines and shows the readings in a bar chart. They are:','["avoiding data", "ignoring numbers", "collecting and organizing data in graphs, tables and charts", "only drawing pictures"]'::jsonb,2,'Organize data visually.','original'),
('127.875.d.6.C',4,'A table of engine hours and oil-change dates is most useful for:','["planning a party", "setting pay", "choosing paint", "spotting patterns in maintenance intervals"]'::jsonb,3,'Tables reveal patterns.','original'),
('127.875.d.6.D',3,'A technician studies a chart of compression readings and sees one cylinder far below the others. She is:','["analyzing and interpreting data from graphs, tables and charts", "guessing", "avoiding reading", "ignoring results"]'::jsonb,0,'Interpret the data.','original'),
('127.875.d.6.D',4,'If a line graph of engine temperature shows a steady rise over 10 minutes, the engine is most likely:','["off", "heating up under load", "freezing", "cooling down"]'::jsonb,1,'Rising line means rising temperature.','original'),
('127.875.d.6.E',3,'A student calculates the engine''s compression ratio by dividing total cylinder volume by the combustion chamber volume. She is:','["bargaining", "guessing", "using a mathematical formula for engine calculations", "painting"]'::jsonb,2,'Compression ratio is a ratio.','original'),
('127.875.d.6.E',4,'If total cylinder volume is 90 cc and clearance volume is 10 cc, the compression ratio is:','["80 to 1", "100 to 1", "8 to 1", "9 to 1"]'::jsonb,3,'90 ÷ 10 = 9.','original'),
('127.875.d.6.F',3,'A student uses Power = Voltage × Current to find the watts consumed by a small starter circuit. She is:','["using a mathematical formula for electrical calculations", "measuring fuel", "measuring oil", "painting a wire"]'::jsonb,0,'Power formula.','original'),
('127.875.d.6.F',4,'A circuit has 12 volts and 5 amps. The power used is:','["7 watts", "60 watts", "17 watts", "2.4 watts"]'::jsonb,1,'12 × 5 = 60.','original'),
('127.875.d.6.G',3,'A technician uses a digital multimeter to measure 6 ohms across a coil and 12 volts applied. She applies Ohm''s law to predict:','["the oil level", "the tire pressure", "the current flowing in the circuit", "the fuel octane"]'::jsonb,2,'I = V ÷ R.','original'),
('127.875.d.6.G',4,'At 12 volts across 6 ohms, the current is:','["18 amps", "0.5 amps", "72 amps", "2 amps"]'::jsonb,3,'12 ÷ 6 = 2.','original'),
('127.875.d.6.H',3,'A technician finds no continuity through a charging coil and replaces it. She is applying:','["electrical principles to diagnose and repair small engine components", "paint", "guesswork", "random swaps"]'::jsonb,0,'Test, then repair.','original'),
('127.875.d.6.H',4,'An open circuit in the ignition kill-switch wire would cause:','["a cooler engine", "no spark, because current cannot flow", "stronger spark", "extra spark"]'::jsonb,1,'Open means no path.','original'),
('127.875.d.7.A',3,'A technician emails a quote and searches a supplier''s website for a discontinued gasket. She is using:','["hand tools only", "only paper", "personal management software such as email and Internet applications", "no software"]'::jsonb,2,'Email and web aid work.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_127'
from (values
('127.875.d.7.A',4,'A shop''s calendar program can help a technician by:','["torquing bolts", "measuring valves", "sharpening blades", "scheduling repair appointments and sending reminders"]'::jsonb,3,'Calendars schedule.','original'),
('127.875.d.7.B',3,'A turf-care company tracks each mower''s route and mapped fields using satellite data. They are discussing:','["Geographic Information Systems and Global Positioning Systems", "hand signals", "a paper chart", "telephone poles"]'::jsonb,0,'GIS and GPS.','original'),
('127.875.d.7.B',4,'A GPS receiver on a piece of equipment provides its:','["spark gap", "location, speed and route", "tire tread", "engine oil type"]'::jsonb,1,'GPS gives position.','original'),
('127.875.d.7.C',3,'A technician plugs a diagnostic laptop into an engine control module to read live sensor data. This is:','["manual only", "guessing", "using computer-based equipment", "unrelated to repair"]'::jsonb,2,'Computers diagnose.','original'),
('127.875.d.7.C',4,'A computer-based diagnostic tool is useful because it can:','["replace parts", "sharpen blades", "change oil", "show stored fault codes and live data quickly"]'::jsonb,3,'Speeds diagnosis.','original'),
('127.875.d.8.A',3,'A student demonstrates how a generator engine, a tiller engine and a pump engine are each matched to a job. She is demonstrating:','["the use and application of small engines and components", "packaging", "shipping", "paint"]'::jsonb,0,'Match engine to task.','original'),
('127.875.d.8.A',4,'A small engine rated for continuous duty is best suited for a:','["toy", "generator that runs for hours", "bike bell", "wall clock"]'::jsonb,1,'Duty cycle matters.','original'),
('127.875.d.8.B',3,'A student traces current from the battery through the switch, coil and spark plug on a diagram. She is demonstrating:','["exhaust parts", "cooling parts", "the components of electrical-electronic systems", "fuel parts"]'::jsonb,2,'Trace the circuit.','original'),
('127.875.d.8.B',4,'The device that allows current to flow in only one direction in a charging circuit is the:','["carburetor", "dipstick", "muffler", "rectifier"]'::jsonb,3,'Rectifier converts AC to DC.','original'),
('127.875.d.8.C',3,'A technician compares side-valve, overhead-valve and two-cycle designs and the jobs each suits. He is demonstrating:','["knowledge of engine designs, components and applications", "menu planning", "paint mixing", "tire shopping"]'::jsonb,0,'Designs differ.','original'),
('127.875.d.8.C',4,'Overhead-valve engines are often favored over side-valve engines because they:','["never overheat", "breathe better and burn fuel more efficiently", "use no oil", "lack a camshaft"]'::jsonb,1,'Better combustion chamber.','original'),
('127.875.d.8.D',3,'A student reads cylinder wear with a dial bore gauge and tests the ignition with a spark tester. She is demonstrating:','["only visual checks", "paint matching", "the correct use of engine measuring tools and test equipment", "guessing"]'::jsonb,2,'Use the right tool.','original'),
('127.875.d.8.D',4,'A dial bore gauge measures a cylinder''s:','["oil color", "tire tread", "outside paint thickness", "inside diameter and any out-of-round wear"]'::jsonb,3,'Bore gauges measure the inside.','original'),
('127.875.d.9.A',3,'A walk-behind mower surges, then stalls. The technician checks the fuel, filters the air and cleans the carburetor. She is:','["troubleshooting and repairing a small engine", "shopping", "guessing", "painting"]'::jsonb,0,'Systematic diagnosis.','original'),
('127.875.d.9.A',4,'After finding a stale-fuel varnish clog in a carburetor, the technician should also:','["skip the test run", "drain the old fuel and verify the engine runs properly", "only repaint", "ignore the tank"]'::jsonb,1,'Fix root cause.','original'),
('127.875.d.9.B',3,'A technician follows a seasonal list: change oil, replace the air filter, sharpen the blade and install a fresh spark plug. She is:','["waiting for failure", "ignoring care", "performing preventative maintenance on small engines", "avoiding service"]'::jsonb,2,'Routine service.','original'),
('127.875.d.9.B',4,'The main purpose of replacing an air filter on schedule is to:','["use more fuel", "cool the exhaust", "make it louder", "prevent dirt from entering and wearing the engine"]'::jsonb,3,'Clean air protects engines.','original'),
('127.875.d.9.C',3,'A technician tests a 4-stroke engine on regular gasoline and a leaner setting, then compares fuel use. She is:','["assessing fuel mixtures and analyzing efficiency", "guessing", "painting", "ignoring fuel"]'::jsonb,0,'Test and compare.','original'),
('127.875.d.9.D',3,'A student adjusts valve lash and aligns the cam timing marks on an overhead-valve engine. She is:','["sharpening tools", "distinguishing valve arrangement positions and analyzing valve timing", "tuning a guitar", "setting tire pressure"]'::jsonb,1,'Valve train work.','original'),
('127.875.d.9.D',4,'If an intake valve opens too late, the engine will likely:','["gain power", "run cooler only", "lose power from poor cylinder filling", "use less oil"]'::jsonb,2,'Late opening starves the cylinder.','original'),
('127.875.d.9.C',4,'A lean air-fuel mixture in an engine commonly causes:','["cooler running", "no change", "extra lubrication", "overheating and possible engine damage"]'::jsonb,3,'Lean runs hot.','original'),
('127.875.d.9.E',3,'A student changes the oil, tests the cooling fins for debris and checks the oil pump pickup screen. He is:','["performing preventative maintenance on lubrication and cooling systems", "avoiding service", "painting", "guessing"]'::jsonb,0,'Lube and cool.','original'),
('127.875.d.9.E',4,'Oil in an engine mainly reduces:','["air flow", "friction and wear, and helps carry heat away", "horsepower", "fuel use only"]'::jsonb,1,'Oil lubricates and cools.','original'),
('127.875.d.9.F',3,'A technician installs a new recoil starter, inspects the muffler bolts and adjusts the governor linkage. She is:','["guessing", "only painting", "performing routine installations, inspections, adjustments and maintenance", "ignoring tasks"]'::jsonb,2,'Routine service.','original'),
('127.875.d.9.F',4,'After adjusting an engine''s governor, the technician should:','["leave without testing", "guess the speed", "paint the housing", "test the engine speed with a tachometer"]'::jsonb,3,'Verify the adjustment.','original'),
('127.875.d.9.G',3,'A student connects a multimeter, a timing light and a spark tester to a magneto ignition. She is demonstrating:','["knowledge of electrical testing tools and equipment common to small engines", "only cleaning", "only cutting", "only painting"]'::jsonb,0,'Test equipment.','original'),
('127.875.d.9.G',4,'A timing light is used to check:','["fuel octane", "when the spark occurs relative to piston position", "oil color", "tire pressure"]'::jsonb,1,'Timing light shows spark timing.','original'),
('127.875.d.9.H',3,'A student reads 0.750 inch on an outside micrometer measuring a piston pin. She is:','["guessing", "using a yardstick", "performing measurements using precision instruments", "avoiding tools"]'::jsonb,2,'Micrometers measure precisely.','original'),
('127.875.d.9.H',4,'An outside micrometer can measure to a precision of:','["0.5 inch", "0.1 inch", "1 inch", "0.001 inch"]'::jsonb,3,'Thousandths.','original'),
('127.875.d.9.I',3,'A technician measures a crankshaft journal and compares the reading with the manufacturer''s wear limit. She is:','["inspecting and measuring engine parts for wear tolerances and comparing them to specifications", "ignoring specs", "guessing", "painting"]'::jsonb,0,'Compare to spec.','original'),
('127.875.d.9.I',4,'A measured piston-to-wall clearance greater than the service limit means the part:','["needs paint", "is worn beyond tolerance and needs replacement or machining", "can stay", "is like new"]'::jsonb,1,'Out of tolerance.','original'),
('127.875.d.9.J',3,'A student shows that a moving magnet next to a wire coil produces voltage, as in a flywheel magneto. She is demonstrating:','["fuel flow", "oil flow", "the relationship between electric current and magnetic fields", "air flow"]'::jsonb,2,'Electromagnetic induction.','original'),
('127.875.d.9.J',4,'Which part of a flywheel magneto passes the magnets near the coil?','["the air cleaner", "the carburetor", "the muffler", "the spinning flywheel"]'::jsonb,3,'The flywheel carries the magnets.','original'),
('127.875.d.9.K',3,'A technician finds a hot engine has a tighter piston fit than the same engine when cold. She is analyzing:','["the effects of heating and cooling on small engines", "fuel pricing", "tire wear", "paint color"]'::jsonb,0,'Thermal expansion.','original'),
('127.875.d.9.K',4,'Aluminum pistons expand faster than iron cylinders when heated, so they are fitted with:','["no clearance", "a clearance to prevent seizing", "tape", "paint"]'::jsonb,1,'Allow for expansion.','original'),
('127.875.d.9.L',3,'A student compares how thick a lubricating oil is at room temperature and when hot. She is explaining:','["packaging", "colors only", "the thermophysical properties of fluids used in small engines", "pricing"]'::jsonb,2,'Viscosity changes with heat.','original'),
('127.875.d.9.L',4,'A fluid''s viscosity describes its:','["color", "smell", "price", "resistance to flow"]'::jsonb,3,'Thickness.','original'),
('127.875.d.9.M',3,'A student explains that energy cannot be created or destroyed, only changed from chemical to heat to motion in an engine. She is explaining:','["the laws of thermodynamics", "motion pictures", "tire laws", "parking rules"]'::jsonb,0,'First law.','original'),
('127.875.d.9.M',4,'The second law of thermodynamics helps explain why no engine can:','["make heat", "convert all fuel energy into useful work", "burn fuel", "run at all"]'::jsonb,1,'Some energy always becomes waste heat.','original'),
('127.875.d.9.N',3,'A student explains that torque twists the crankshaft, horsepower measures how fast work is done and some heat leaves through the exhaust. She is explaining:','["fuel taxes", "tires", "torque, horsepower and heat energy transfer in small engines", "paint"]'::jsonb,2,'Three key ideas.','original'),
('127.875.d.9.N',4,'Horsepower is a measure of:','["fuel color", "oil price", "engine weight only", "the rate at which an engine does work"]'::jsonb,3,'Power is work over time.','original'),
('127.875.d.9.O',3,'A technician times an engine''s crankshaft at 3,600 revolutions each minute and calculates how fast the piston travels. She is:','["calculating speed in small engines", "guessing", "naming parts", "painting"]'::jsonb,0,'Speed calculations.','original'),
('127.875.d.9.O',4,'A mower engine speeds up from 2,000 rpm to 3,000 rpm in 5 seconds. Its acceleration is:','["500 rpm per second", "200 rpm per second", "1,000 rpm per second", "15,000 rpm per second"]'::jsonb,1,'1,000 ÷ 5 = 200.','original'),
('127.875.d.9.P',3,'A student compares the fuel used by a 3-hp and a 10-hp engine for the same job. She is:','["painting", "guessing", "comparing the efficiency of various engine sizes and types", "naming tires"]'::jsonb,2,'Compare efficiency.','original'),
('127.875.d.9.P',4,'An engine is more efficient when it:','["burns more fuel", "wastes more heat", "runs hotter", "converts more of the fuel''s energy into useful work"]'::jsonb,3,'Efficiency means less waste.','original'),
('127.876.d.1.A',3,'A new automotive technician is asked to sign off an inspection he did not perform. His ethical and legal responsibility is to:','["refuse and report only what he actually did", "hide the form", "sign it anyway", "ask a friend to sign"]'::jsonb,0,'Honest records.','original'),
('127.876.d.1.A',4,'Which action best shows that a shop meets its legal duty for customers'' safety?','["ignoring the manual", "repairing brake defects before returning the vehicle", "skipping inspection", "hiding the defect"]'::jsonb,1,'Fix safety items.','original'),
('127.876.d.1.B',3,'A trainee listens quietly while a veteran technician explains a procedure and thanks him afterward. She is showing:','["lateness", "carelessness", "proper etiquette and behavior", "rudeness"]'::jsonb,2,'Respect and gratitude.','original'),
('127.876.d.1.B',4,'A customer is upset that her car is not finished. The technician should:','["avoid her", "argue", "promise a false time", "apologize for the delay and give a realistic update"]'::jsonb,3,'Honest, calm.','original'),
('127.876.d.1.C',3,'An apprentice washes his hands, trims his sleeves and secures his hair before starting work. He is showing:','["appropriate personal appearance and hygiene", "unsafe dress", "laziness", "poor habits"]'::jsonb,0,'Clean and safe.','original'),
('127.876.d.1.C',4,'Long, loose sleeves are discouraged in a service bay because they can:','["improve grip", "catch in rotating parts like belts and fans", "save time", "reduce noise"]'::jsonb,1,'Entanglement hazard.','original'),
('127.876.d.1.D',3,'A technician emails the parts desk a request and speaks with a customer to confirm pickup. She is using:','["avoidance", "text speak only", "effective written and oral communication skills and employability", "silence"]'::jsonb,2,'Clear communication.','original'),
('127.876.d.1.D',4,'Which habit shows good listening during a customer''s complaint?','["interrupting", "looking at a phone", "walking away", "repeating the concern back to confirm understanding"]'::jsonb,3,'Confirm understanding.','original'),
('127.876.d.1.E',3,'A student writes a step-by-step procedure for replacing a brake pad, with torque values and warnings in numbered order. She is demonstrating:','["advanced technical writing and preparation skills", "story telling", "poetry", "jokes"]'::jsonb,0,'Technical writing.','original'),
('127.876.d.1.E',4,'A well-written technical procedure should have steps that are:','["random", "clear, ordered and complete", "vague", "hidden"]'::jsonb,1,'Clarity.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_127'
from (values
('127.876.d.1.F',3,'A student presents the steps of a tire rotation to a class and answers an unplanned question on the spot. She is demonstrating:','["avoidance", "silent reading", "prepared and extemporaneous speaking", "mumbling"]'::jsonb,2,'Both types.','original'),
('127.876.d.1.F',4,'Which choice makes a technical talk clearer?','["speaking only in jargon", "using no examples", "rushing", "defining unfamiliar terms as you use them"]'::jsonb,3,'Define terms.','original'),
('127.876.d.2.A',3,'A service advisor calmly asks a customer from another town to describe a vibration, then repeats the symptoms back before writing the order. She shows:','["effective oral communication with individuals from varied backgrounds", "impatience", "avoidance", "poor listening"]'::jsonb,0,'Communicate with everyone.','original'),
('127.876.d.2.A',4,'When a customer is unfamiliar with automotive terms, the technician should:','["speak faster", "explain the issue in plain words", "use only jargon", "avoid answering"]'::jsonb,1,'Plain language.','original'),
('127.876.d.2.B',3,'A technician documents a vehicle''s complaint, the cause found and the repair performed on the work order. She is demonstrating:','["avoiding paper", "random notes", "effective written communication, including documentation", "slang only"]'::jsonb,2,'Document the work.','original'),
('127.876.d.2.B',4,'A good written note on a work order is:','["funny", "unsigned", "vague", "accurate, legible and specific"]'::jsonb,3,'Be specific.','original'),
('127.876.d.2.C',3,'A technician multiplies 3.5 hours of labor by $90 and adds a $64 part. She is demonstrating:','["mathematical skills in addition, subtraction, multiplication and division for estimates", "avoiding math", "ignoring prices", "guessing"]'::jsonb,0,'Compute estimates.','original'),
('127.876.d.2.C',4,'If a customer has a $380 repair bill and a $50 coupon, the amount due is:','["$430", "$330", "$300", "$350"]'::jsonb,1,'380 − 50 = 330.','original'),
('127.876.d.3.A',3,'A student labels a diagram with the engine, fuel, electrical, cooling, exhaust, drivetrain, suspension and brake systems. She is describing:','["tire types", "trim levels", "the eight major vehicle systems", "paint finishes"]'::jsonb,2,'Eight systems.','original'),
('127.876.d.3.A',4,'Which is one of the eight major vehicle systems?','["the radio dial", "the wiper blade", "the cup holder", "the steering and suspension system"]'::jsonb,3,'Part of the eight.','original'),
('127.876.d.3.B',3,'A technician looks up the oil capacity and the recommended service interval for a specific car in the maintenance guide. She is:','["locating, reading and interpreting vehicle maintenance and service information", "guessing", "ignoring the manual", "using memory only"]'::jsonb,0,'Look it up.','original'),
('127.876.d.3.B',4,'Before replacing a timing belt, the technician should consult:','["her memory only", "the manufacturer''s service procedure for that vehicle", "a friend", "a random video"]'::jsonb,1,'Follow the manufacturer.','original'),
('127.876.d.3.C',3,'A student explains how gasoline, diesel, hybrid and battery-electric vehicles supply power to the wheels. She is describing:','["tire sizes", "paint types", "basic and emerging vehicle power systems", "horse power"]'::jsonb,2,'Many power systems.','original'),
('127.876.d.3.C',4,'A key difference between a hybrid and a conventional vehicle is that a hybrid:','["uses only wind", "has no engine ever", "has no brakes", "pairs an engine with an electric motor and battery"]'::jsonb,3,'Hybrid combines two sources.','original'),
('127.876.d.4.A',3,'A student puts on safety glasses, checks that a drill''s guard is in place and clamps the work before drilling. She is demonstrating:','["the proper way to safely use hand and power tools and equipment", "unsafe habits", "ignoring rules", "carelessness"]'::jsonb,0,'Tool safety.','original'),
('127.876.d.4.A',4,'Before using a power tool, a technician should inspect its cord and guards because:','["it saves time", "damage could cause shock or injury", "no one checks", "it saves paint"]'::jsonb,1,'Prevent accidents.','original'),
('127.876.d.4.B',3,'A shop sends used antifreeze and old brake fluid to licensed recyclers. This is the proper:','["dumping practice", "drain disposal", "handling and disposal of environmentally hazardous materials", "trash disposal"]'::jsonb,2,'Hazmat rules.','original'),
('127.876.d.4.B',4,'Safety Data Sheets (SDS) help a technician by describing:','["its brand history", "its color only", "its price", "a chemical''s hazards and how to handle it safely"]'::jsonb,3,'SDS tell hazards.','original'),
('127.876.d.4.C',3,'A technician connects a scan tool to the vehicle''s data port and reads the fault codes. She is:','["identifying diagnostic tools and equipment", "using a hammer", "guessing", "painting"]'::jsonb,0,'Diagnostic tools.','original'),
('127.876.d.4.C',4,'A digital multimeter is used to measure:','["paint depth", "voltage, resistance and current", "oil color", "tire wear"]'::jsonb,1,'Electrical testing.','original'),
('127.876.d.4.D',3,'A technician selects a socket set, a breaker bar and a torque wrench for a wheel job. She is:','["ignoring tools", "misusing tools", "identifying hand and shop tools and describing their proper usage", "guessing"]'::jsonb,2,'Right tool.','original'),
('127.876.d.4.D',4,'A torque wrench should be used to:','["hammer parts", "cut metal", "break bolts loose", "tighten fasteners to a specified value"]'::jsonb,3,'Measures torque.','original'),
('127.876.d.5.A',3,'A parts counter worker looks up a filter by year, make, model and engine, then confirms the part number. This demonstrates:','["the procedures for ordering and locating parts", "luck", "guesswork", "skipping steps"]'::jsonb,0,'Use a catalog.','original'),
('127.876.d.5.A',4,'The most reliable way to find a part is to match:','["the color", "the vehicle''s VIN with the part number", "the radio", "the price only"]'::jsonb,1,'VIN identifies exactly.','original'),
('127.876.d.5.B',3,'A student walks through intake, compression, power and exhaust strokes on a model. She is demonstrating:','["tire theory", "car painting", "the operating theory of an internal combustion engine", "brake theory"]'::jsonb,2,'Four strokes.','original'),
('127.876.d.5.B',4,'In a four-stroke engine, the stroke in which the spark ignites the compressed mixture is the:','["compression stroke", "intake stroke", "exhaust stroke", "power stroke"]'::jsonb,3,'Power from combustion.','original'),
('127.876.d.5.C',3,'A student labels a rotor, caliper, pads, a drum, shoes and a booster on a brake diagram. She is identifying:','["brake system components", "engine parts", "tire parts", "paint parts"]'::jsonb,0,'Brake components.','original'),
('127.876.d.5.C',4,'Disc brakes slow a vehicle when the caliper squeezes the pads against the:','["axle", "rotor", "tire", "muffler"]'::jsonb,1,'Pads clamp the rotor.','original'),
('127.876.d.5.D',3,'A student explains that pressing the brake pedal pushes fluid through lines to the wheels, where pressure moves the pads. She is demonstrating:','["ignition timing", "tire rotation", "basic concepts related to hydraulic brake systems", "fuel injection"]'::jsonb,2,'Hydraulics.','original'),
('127.876.d.5.D',4,'Brake fluid is used in a hydraulic system because liquids:','["evaporate fast", "are cheap", "burn quickly", "do not compress easily and transmit force"]'::jsonb,3,'Fluid transfers pressure.','original'),
('127.876.d.5.E',3,'A student traces the battery, fuse, switch and headlight on a wiring diagram. She is demonstrating:','["basic concepts related to electrical and electronic systems", "fuel systems", "tire systems", "cooling systems"]'::jsonb,0,'Circuit basics.','original'),
('127.876.d.5.E',4,'The purpose of a fuse in a vehicle circuit is to:','["store energy", "protect the circuit by melting when current is too high", "increase voltage", "speed the engine"]'::jsonb,1,'Fuses protect.','original'),
('127.876.d.5.F',3,'A student identifies the compressor, condenser, evaporator and blower motor in the cabin cooling system. She is identifying:','["engine blocks", "brake parts", "air-conditioning, heating and accessory system components", "tire valves"]'::jsonb,2,'HVAC parts.','original'),
('127.876.d.5.F',4,'The component that removes heat from the refrigerant in an A/C system is the:','["fuse", "horn", "wiper", "condenser"]'::jsonb,3,'Condenser sheds heat.','original'),
('127.876.d.5.G',3,'A technician inspects a CV axle boot, a drive shaft and the transmission mount. She is inspecting:','["chassis and power train components and systems", "decals", "paint", "seat covers"]'::jsonb,0,'Chassis and power train.','original'),
('127.876.d.5.G',4,'A torn CV joint boot is a problem because it:','["reduces tire wear", "lets grease escape and dirt enter, damaging the joint", "adds power", "improves the ride"]'::jsonb,1,'Boots protect joints.','original'),
('127.876.d.5.H',3,'A student labels the radiator, water pump, thermostat and oil filter on an engine. She is identifying:','["brake parts", "paint parts", "cooling and lubrication system components", "tire parts"]'::jsonb,2,'Cooling and oil.','original'),
('127.876.d.5.H',4,'The thermostat in a cooling system:','["lights the dash", "filters air", "stores fuel", "regulates coolant flow to control engine temperature"]'::jsonb,3,'Opens when hot.','original'),
('127.876.d.5.I',3,'A technician inspects tie rods, ball joints, struts and the power steering pump. She is identifying:','["steering and suspension components, including power steering", "radio parts", "fuel parts", "paint parts"]'::jsonb,0,'Steering and suspension.','original'),
('127.876.d.5.I',4,'A worn tie rod end would most likely cause:','["a cooler engine", "loose steering and uneven tire wear", "better mileage", "a louder radio"]'::jsonb,1,'Worn steering parts.','original'),
('127.876.d.5.J',3,'A technician reads a tire sidewall code that shows size, load index and the Department of Transportation date code. She is:','["painting", "ignoring labels", "identifying and interpreting tire sidewall data", "guessing"]'::jsonb,2,'Read the sidewall.','original'),
('127.876.d.5.J',4,'The DOT code on a tire sidewall tells a technician the tire''s:','["price", "color", "owner", "manufacturing week and year"]'::jsonb,3,'Date code.','original'),
('127.876.d.5.K',3,'A technician compares the recommended service intervals for a sedan, a diesel truck and a hybrid. She is:','["comparing the preventative maintenance schedules for a variety of vehicles", "guessing", "ignoring schedules", "painting"]'::jsonb,0,'Schedules differ.','original'),
('127.876.d.5.K',4,'A vehicle used for towing or in dusty conditions typically requires:','["less maintenance", "more frequent maintenance than normal driving", "maintenance only yearly", "no maintenance"]'::jsonb,1,'Severe service shortens intervals.','original'),
('127.876.d.5.L',3,'A technician checks fluid levels, tire pressure, belts, lights and brakes on a customer''s car using a checklist. She is performing:','["a rebuild", "a paint job", "a preventative maintenance inspection", "a sale"]'::jsonb,2,'PM inspection.','original'),
('127.876.d.5.L',4,'The main goal of a preventative maintenance inspection is to:','["avoid service", "cause delays", "increase cost", "find small problems before they cause breakdowns"]'::jsonb,3,'Prevent failures.','original'),
('127.876.d.5.M',3,'A driver''s battery is dead, and a technician connects jumper cables positive to positive, then negative to the dead car''s metal frame. She is:','["explaining and performing a jump-start properly", "doing a repair", "wasting time", "using wrong cables"]'::jsonb,0,'Proper jump-start.','original'),
('127.876.d.5.M',4,'The last jumper cable clamp should be connected to an unpainted metal ground away from the battery to:','["look neat", "avoid sparks near the battery''s explosive gases", "speed charging", "save cable"]'::jsonb,1,'Prevent explosions.','original'),
('127.876.d.5.N',3,'A technician performs a monthly audit of fire extinguishers, eyewash stations and lift certification. She is performing:','["decorating", "ignoring safety", "regular audits and inspections to maintain compliance with safety requirements", "avoiding records"]'::jsonb,2,'Compliance audits.','original'),
('127.876.d.5.N',4,'A regular safety inspection is important because it:','["costs more", "adds paperwork only", "ruins schedules", "finds hazards and keeps the shop in compliance with regulations"]'::jsonb,3,'Prevents injuries and fines.','original')
